import { Component, Prop, State, h, Host } from '@stencil/core';

@Component({
  tag: 'dda-accordion',
  styleUrls: ['dda-accordion.css', '../../global/global.css'],
  shadow: false,
})
export class DdaAccordion {
  @Prop() design: 'bg-border' | 'no-border' = 'bg-border'; // Default to background and border design
  @Prop() header_text: string = 'Accordion Header'; // Default header text
  @Prop() body_description: string = ''; // Default body description
  @Prop() custom_class?: string = '';
  @Prop() component_mode?: string;
  @Prop() accordion_icon: string = 'info'; // Default Material icon

  @State() isOpen: boolean = false;

  toggleAccordion() {
    this.isOpen = !this.isOpen;
  }

  render() {
    return (
      <Host>
        <div class={`accordion-container ${this.design} ${this.custom_class} ${this.component_mode}`}>
          <div class="accordion-header" onClick={() => this.toggleAccordion()}>
            {/* <span class="material-symbols-outlined">pen_size_1</span>
<span class="material-symbols-rounded">face</span>
<span class="material-symbols-sharp">face</span> */}
            <div class="header-content">
              <i class="material-icons  material-symbols-outlined">{this.accordion_icon}</i>
              <span class="header-text">{this.header_text}</span>
            </div>
            <i class={`material-icons arrow-icon`}>{this.isOpen ? 'keyboard_arrow_up' : 'keyboard_arrow_down'}</i>
          </div>
          <div class={this.isOpen ? 'accordion-body' : 'dda-d-none'}>
            <p class="body-description">{this.body_description}</p>
            <slot></slot>
          </div>
        </div>
      </Host>
    );
  }
}

import { Component, Prop, h, Event, EventEmitter } from '@stencil/core';

@Component({
  tag: 'dda-alert',
  styleUrls: ['dda-alert.css', '../../global/global.css', '../../global/dda-button.css'],
  shadow: false,
})
export class DdaAlert {
  @Prop() type: 'primary' | 'secondary' = 'primary';
  @Prop() variation: 'info' | 'warning' | 'error' | 'success' = 'info';
  @Prop() title_text: string = '';
  @Prop() description: string = '';
  @Prop() button_text: string = '';
  @Prop() custom_class?: string = '';
  @Prop() component_mode?: string;
  @Prop() component_id?: string;
  @Prop() first_link?: string;
  @Prop() second_link?: string;
  @Prop() first_button?: string;
  @Prop() second_button?: string;
  @Prop() button_name?: string;
  @Prop() clickHandler?: (event: MouseEvent) => void;
  @Event() firstClick?: EventEmitter<void>;
  @Event() secondClick?: EventEmitter<void>;

  private firstClickHandler = () => {
    this.firstClick.emit();
  };

  private secondClickHandler = () => {
    this.secondClick.emit();
  };

  render() {
    return (
      <div class={`dda-alert dda-alert-${this.type} dda-alert-${this.variation} ${this.custom_class} ${this.component_mode}`}>
        <i class="material-icons  material-symbols-outlined">info</i>
        <div class="alert-content">
          <h4 class="alert-title">{this.title_text}</h4>
          <p class="alert-description">{this.description}</p>
          <div class="alert-btn-wrap">
            {!!this.first_button && (
              <a href={this.first_link} onClick={() => this.firstClickHandler()}>
                {this.first_button}
              </a>
            )}
            {!!this.second_button && (
              <a href={this.second_link} onClick={() => this.secondClickHandler()}>
                {this.second_button}
              </a>
            )}
          </div>
        </div>
        <button name={this.button_name} class="dda-alert-close" onClick={this.clickHandler}>
          <i class="material-icons  material-symbols-outlined">close</i>
        </button>
      </div>
    );
  }
}

import { Component, Prop, State, h, Host } from '@stencil/core';
import pdfIcon from '../../assets/img/icn/icn-PDF.svg';
import pptIcon from '../../assets/img/icn/icn-PowerPoint.svg';
import wordIcon from '../../assets/img/icn/icn-Word.svg';
import excelIcon from '../../assets/img/icn/icn-Excel.svg';
import imageIcon from '../../assets/img/icn/icn-Image.svg';
import videoIcon from '../../assets/img/icn/icn-Video.svg';
import onenoteIcon from '../../assets/img/icn/icn-OneNote.svg';

@Component({
  tag: 'dda-attach-file',
  styleUrls: ['../../global/input.css', '../../global/global.css'],
  shadow: false,
})
export class DdaAttachFile {
  @Prop() label: string;
  @Prop() helper_text: string;
  @Prop() error_message: string;
  @Prop() size?: string;
  @Prop() validation_type?: string;
  @Prop() input_type?: string;
  @State() file: File | null = null;
  @Prop() custom_class?: string = ''; 
  @Prop() component_mode?: string; 
  @Prop() aria_label?: string = '';
  @Prop() button_aria_label?: string = '';
  @Prop() input_id: string;
  @Prop() button_id: string;
  @Prop() button_name?: string;
  @Prop() input_name?: string;

  private fileIcons = {
    pdf: pdfIcon,
    pptx: pptIcon,
    docx: wordIcon,
    xlsx: excelIcon,
    png: imageIcon,
    jpg: imageIcon,
    jpeg: imageIcon,
    mp4: videoIcon,
    mkv: videoIcon,
    one: onenoteIcon,
  };

  handleFileInput(event) {
    const files = event.target.files;
    if (files.length > 0) {
      this.file = files[0];
    } else {
      this.file = null;
    }
  }

  removeFile() {
    this.file = null;
  }

  getFileIcon(fileName: string) {
    const extension = fileName.split('.').pop().toLowerCase();
    return this.fileIcons[extension] || 'path/to/default-icon.png';
  }

  render() {
    const inputClass = [
      'dda-input-container',
      this.validation_type ? `dda-validation-${this.validation_type}` : '',
      this.size ? `dda-input-size-${this.size}` : '',
      this.input_type ? `dda-input-${this.input_type}` : '',
      this.custom_class,
      this.component_mode,
    ].filter(Boolean).join(' ');

    return (
      <Host>
        <div class={inputClass}>
          {this.label && <label htmlFor={this.input_id} class="dda-input-label">{this.label}</label>}
          <div class="dda-input-field-group dda-attach-file">
            {this.file ? (
              <div class="dda-file-details">
                <div class="dda-items">
                  <img src={this.getFileIcon(this.file.name)} alt="File Icon" class="dda-file-icon" />
                  <span class="dda-file-name">{this.file.name}</span>
                </div>
                <button id={this.button_id} name={this.button_name} aria-label={this.button_aria_label} class="remove-file" onClick={() => this.removeFile()}>
                  <i class="material-icons  material-symbols-outlined" aria-hidden="true">close</i>
                </button>
              </div>
            ) : (
              <div class="dda-file-input">
                <span>No File Selected</span>
                <label htmlFor={this.input_id} class="dda-file-choose">
                  Choose File
                  <input id={this.input_id} name={this.input_name} aria-label={this.aria_label} type="file" onInput={(event) => {this.handleFileInput(event)}} />
                </label>
              </div>
            )}
          </div>
          {this.helper_text && <span class="dda-helper-text">{this.helper_text}</span>}
          {this.error_message && <span class="dda-error-message">{this.error_message}</span>}
        </div>
      </Host>
    );
  }
}

import { Component, Prop, State, h } from '@stencil/core';

@Component({
  tag: 'dda-avatar',
  styleUrls: ['dda-avatar.css', '../../global/input.css', '../../global/global.css'],
  shadow: false,
})
export class DdaAvatar {
  @Prop() type: 'photo' | 'icon' | 'text' = 'photo';
  @Prop() size: 'xs' | 'sm' | 'md' | 'lg' | 'xl' | 'xxl' = 'md';
  @Prop() design: 'default' | 'status' | 'verified' | 'story' | 'notification' = 'default';
  @Prop() rounded: 'square' | 'circle' = 'circle';
  @Prop() src: string = ''; // For photo type
  @Prop() icon: string = 'material-icons'; // For icon type
  @Prop() text: string = 'AB'; // For text type
  @Prop() notification_number: number = 0; // For notification design
  @Prop() custom_class?: string = ''; 
  @State() isOpen: boolean = false;
  @Prop() selected: string;
  @Prop() options: string;
  @Prop() component_mode?: string; 
  @Prop() aria_label: string;
  @Prop() button_id?: string;
  @Prop() button_name?: string;

  toggleDropdown() {
    this.isOpen = !this.isOpen;
  }

  selectOption(option: string) {
    this.selected = option
    this.isOpen = false
  }

  private get parsedOptions(): string[] {
    try {
      return JSON.parse(this.options);
    } catch {
      return [];
    }
  }

  render() {
    return (
      <div onClick={() => this.toggleDropdown()} class={{
        'dda-avatar': true,
        [`avatar-type-${this.type}`]: true,
        [`avatar-size-${this.size}`]: true,
        [`avatar-design-${this.design}`]: true,
        [`avatar-shape-${this.rounded}`]: true,
        [`${this.custom_class}`]: true,
        [`${this.component_mode}`]: true,
        [`${this.button_name}`]: true,
      }}>
      {this.isOpen && (
        <div class="dda-input-dropdown-list">
          {this.parsedOptions.length > 0 ? (
            this.parsedOptions.map(option => (
              <button id={this.button_id} name={this.button_name} aria-label={this.aria_label} type="button"
                class={`dda-input-dropdown-item ${this.selected === option ? 'selected' : ''}`}
                onClick={() => {this.selectOption(option)}}
              >
                {option}
              </button>
            ))
          ) : (
            <div class="dda-input-dropdown-item">No options available</div>
          )}
        </div>
      )}
        {this.type === 'photo' && <img src={this.src} alt="Avatar" />}
        {this.type === 'icon' && <i class={`${this.icon} dda-smile`}>sentiment_satisfied</i>}
        {this.type === 'text' && <span class='avatar-main-text'>{this.text}</span>}
        {this.design === 'status' && <div class="status-circle"></div>}
        {this.design === 'verified' && <div class="verified-icon"><span class="material-icons  material-symbols-outlined">verified</span></div>}
        {this.design === 'notification' && <div class="notification-circle">{this.notification_number}</div>}
      </div>
    );
  }
}

import { Component, Prop, State, h, Host } from '@stencil/core';

@Component({
  tag: 'dda-banner',
  styleUrls: ['dda-banner.css', '../../global/global.css'],
  shadow: true,
})
export class DdaBanner {
  @Prop() slides: string; // JSON string of slides;
  @Prop() slider_width: string;
  @Prop() slider_height: string;
  @State() parsedSlides: { image: string; title: string; subtitle: string; link: string }[] = [];

  componentWillLoad() {
    this.parsedSlides = JSON.parse(this.slides);
  }

  render() {
    return (
      <Host>
        <div class={'dda-banner-slider'}>
          {this.parsedSlides.map((slide) => (
            <div class={'dda-banner-slide'}>
              <img src={slide.image} alt={slide.title} style={{ width: this.slider_width, height: this.slider_height }} />
            </div>
          ))}
        </div>
        {/* <slot></slot> */}
      </Host>
    );
  }
}

import { Component, Prop, h, Host, Element } from '@stencil/core';

@Component({
  tag: 'dda-breadcrumb',
  styleUrls: ['dda-breadcrumb.css', '../../global/global.css'],
  shadow: false,
})
export class DdaBreadcrumb {
  @Prop() design: 'text' | 'icon-text' | 'icon' = 'text'; // Default to text design
  @Prop() separator: 'chevron_right' | 'pen_size_2' = 'chevron_right'; // Default to chevron separator
  @Prop() custom_class?: string = ''; 
  @Prop() component_mode?: string; 
  @Element() el: HTMLElement;

  breadcrumbs: { text: string; icon: string; url: string }[] = [];

  componentWillLoad() {
    const breadcrumbsData = this.el.getAttribute('data-breadcrumbs');
    if (breadcrumbsData) {
      this.breadcrumbs = JSON.parse(breadcrumbsData);
    }
  }

  render() {
    return (
      <Host>
        <div class={this.component_mode}>
          <nav aria-label="breadcrumb" class={`${this.custom_class}`}>
            <ol class="dda-breadcrumb">
              {this.breadcrumbs && this.breadcrumbs.map((crumb, index) => (
                <li class={`dda-breadcrumb-item ${index === this.breadcrumbs.length - 1 ? 'active' : ''}`}>
                  <a href={crumb.url}>
                    {this.design !== 'text' && <i class={`material-icons`}>{crumb.icon}</i>}
                    {this.design !== 'icon' && <span>{crumb.text}</span>}
                  </a>
                  {index < this.breadcrumbs.length - 1 && (
                    <i class={`material-icons material-symbols-outlined`}>{this.separator}</i>
                  )}
                </li>
              ))}
            </ol>
          </nav>
        </div>
      </Host>
    );
  }
}

import { Host, Component, Prop, h } from '@stencil/core';

@Component({
  tag: 'dda-button',
  styleUrls: ['../../global/dda-button.css', '../../global/global.css'],
  shadow: false,
})
export class DdaButton {
  /** Type of button, e.g., "button", "submit" */
  @Prop() type: string = 'button';
  /** Disable the button */
  @Prop() disabled: boolean = false;
  /** Icon class for the starting icon */
  @Prop() start_icon: string = '';
  @Prop() end_icon: string = ''; // icon class
  @Prop() aria_label?: string = '';
  @Prop() button_color: string = 'primary'; // e.g., 'primary', 'error'
  @Prop() size?: string; // e.g., 'sm', 'md', 'lg'
  @Prop() button_shape?: string = '';
  @Prop() icon_button_shape?: string = '';
  @Prop() gap?: number;
  @Prop() custom_class?: string = ''; // Custom class prop
  @Prop() component_mode?: string;
  @Prop() button_id: string;
  @Prop() button_name?: string = '';
  /** Function to be called on button click */
  @Prop() clickHandler?: (event: MouseEvent) => void;

  render() {
    const buttonClass = [
      'dda-btn',
      `btn-color-${this.button_color}`,
      this.size ? `btn-size-${this.size}` : '',
      this.button_shape ? `btn-shape-${this.button_shape}` : '',
      this.icon_button_shape ? `icon-btn-${this.icon_button_shape}` : '',
      this.gap ? `dda-gap-${this.gap}` : '',
      this.custom_class, // Include custom class
      this.component_mode,
    ].filter(Boolean).join(' ');

    return (
      <Host>
        <button
          id={this.button_id}
          type={this.type}
          class={buttonClass}
          disabled={this.disabled}
          aria-label={this.aria_label}
          onClick={this.clickHandler} // Bind the onClick prop here
          name={this.button_name}
        >
          {this.start_icon && <i class="material-icons  material-symbols-outlined">{this.start_icon}</i>}
          <slot />
          {this.end_icon && <i class="material-icons  material-symbols-outlined">{this.end_icon }</i>}
        </button>
      </Host>
    );
  }
}

import { Component, Prop, h, Host } from '@stencil/core';

@Component({
  tag: 'dda-checkbox',
  styleUrls: ['dda-checkbox.css', '../../global/global.css'],
  shadow: false,
})
export class DdaCheckbox {
  @Prop() title_text: string;
  @Prop() supporting?: string;
  @Prop() group_name?: string;
  @Prop() input_id?: string;
  @Prop() checked: boolean;
  @Prop() checkbox_status?: string;
  @Prop() size?: string; // e.g., 'sm', 'md', 'lg'
  @Prop() style_type?: string; // Default to 'square'
  @Prop() custom_class?: string = ''; 
  @Prop() component_mode?: string; 
  @Prop() aria_label?: string;

  render() {
    const checkboxClass = [
      'dda-checkbox-container',
      this.size ? `dda-checkbox-${this.size}` : '',
      this.style_type ? `dda-checkbox-${this.style_type}` : '',
      this.custom_class ?  this.custom_class : '',
      this.checkbox_status ? `dda-checkbox-${this.checkbox_status}` : '',
      this.component_mode,
    ].filter(Boolean).join(' ');

    return (
      <Host>
        <div class={checkboxClass}>
          <input aria-label={this.aria_label} type="checkbox" id={this.input_id} name={this.group_name} checked={this.checked}/>
          <label htmlFor={this.input_id}>
            <i class="material-icons  material-symbols-outlined">check</i>
            <p>
              <span class="dda-checkbox-title">{this.title_text}</span>
              {this.supporting && <span class="dda-checkbox-supporting">{this.supporting}</span>}
            </p>
          </label>
        </div>
      </Host>
    );
  }
}

import { Component, Prop, h, Host } from '@stencil/core';

@Component({
  tag: 'dda-chip',
  styleUrls: ['dda-chip.css', '../../global/global.css'],
  shadow: false,
})
export class DdaChip {
  @Prop() bg_color: string = 'success';
  @Prop() rounded?: string = '';
  @Prop() icon: string;
  @Prop() show_close_icon: boolean = false;
  @Prop() size?: string; // e.g., 'sm', 'md', 'lg'
  @Prop() custom_class?: string;
  @Prop() component_mode?: string;  
  @Prop() clickHandler?: (event: MouseEvent) => void;

  render() {
    return (
      <Host>
        <div class={`dda-chip dda-chip-${this.bg_color} dda-chip-${this.size} dda-rounded-${this.rounded} ${this.custom_class} ${this.component_mode}`}>
          {this.icon ? <i class="material-icons  material-symbols-outlined">{this.icon}</i> : null}
          <span><slot /></span>
          {this.show_close_icon && (
            <span class="chip-close"   onClick={this.clickHandler}>
              <i class="material-icons  material-symbols-outlined">close</i>
            </span>
          )}
        </div>
      </Host>
    );
  }
}

import { Component, Prop, h, Host } from '@stencil/core';

@Component({
  tag: 'dda-credit-card',
  styleUrls: ['dda-credit-card.css', '../../global/global.css'],
  shadow: false,
})
export class DdaCreditCard {
  @Prop() balance: string;
  @Prop() name: string;
  @Prop() card_number: string;
  @Prop() card_type: string;
  @Prop() design: string;
  @Prop() custom_class?: string = ''; 
  @Prop() component_mode?: string; 

  render() {
    const cardClass = [
      'dda-credit-card-container',
      this.design ? `dda-credit-card-${this.design}` : '',
      this.custom_class ? `${this.custom_class}` : "",
      this.component_mode,
    ].filter(Boolean).join(' ');

    return (
      <Host>
        <div class={cardClass}>
          <div class="dda-credit-card-header">
            <div class="card-balance-info">
              <span class="card-balance-label">Current Balance</span>
