import { Component, Prop,  State, h, Host } from '@stencil/core';

@Component({
  tag: 'dda-creditcard-field',
  styleUrls: ['../../global/input.css', '../../global/global.css'],
  shadow: false,
})
export class DdaCreditCardField {
  @Prop() placeholder: string;
  @Prop() label: string;
  @Prop() value: string = '';
  @Prop() card_icon: string;
  @Prop() error_message: string;
  @Prop() validation_type?: string;
  @Prop() size?: string;
  @Prop() input_type?: string;
  @Prop() helper_text: string;
  @Prop() disabled: boolean = false;
  @Prop() custom_class?: string = '';
  @Prop() restrict_input: boolean = false;
  @Prop() component_mode?: string; 
  @Prop() input_id: string;
  @Prop() aria_label?: string;
  @Prop() input_name?: string;

  @State() formattedValue: string = '';

  handleInput(event: Event) {
    const inputElement = event.target as HTMLInputElement;
    const inputValue = inputElement.value.replace(/[^0-9-]/g, '');
    const maxLength = this.restrict_input ? 100 : 25;

    if (inputValue.length <= maxLength) {
      this.value = inputValue;
      this.formatCardNumber(this.value);
      inputElement.value = this.formattedValue;
    } else {
      inputElement.value = this.formattedValue;
    }
  }

  formatCardNumber(value: string) {
    const cleaned = value.replace(/\D/g, '');
    const matched = cleaned.match(/.{1,4}/g);
    if (matched) {
      this.formattedValue = matched.join(' - ');
    } else {
      this.formattedValue = cleaned;
    }
  }

  componentWillLoad() {
    this.formatCardNumber(this.value);
  }

  render() {
    const inputClass = [
      'dda-input-container dda-credit-card-field',
      this.validation_type ? `dda-validation-${this.validation_type}` : '',
      this.size ? `dda-input-size-${this.size}` : '',
      this.input_type ? `dda-input-${this.input_type}` : '',
      this.disabled ? 'dda-input-disabled' : '',
      this.error_message ? 'dda-error-message' : '',
      this.custom_class ? `${this.custom_class}` : '',
      this.component_mode, 
    ].filter(Boolean).join(' ');

    return (
      <Host>
        <div class={inputClass}>
          {this.label && <label htmlFor={this.input_id} class="dda-input-label">{this.label}</label>}
          <div class="dda-input-field-wrapper">
            {this.card_icon && <img src={this.card_icon} alt="Card Icon" class="dda-creditcard-icon" />}
            <input
              aria-label={this.aria_label}
              id={this.input_id}
              name={this.input_name}
              type="text"
              inputmode="numeric"
              placeholder={this.placeholder}
              value={this.formattedValue}
              onInput={(event) => this.handleInput(event)}
              class="dda-input-field"
              disabled={this.disabled}
              maxlength={this.restrict_input ? 100 : 25}
            />
          </div>
          {this.helper_text && <span class="dda-helper-text">{this.helper_text}</span>}
          {this.error_message && <span class="dda-error-message">{this.error_message}</span>}
        </div>
      </Host>
    );
  }
}

import { Component, Prop, State, h, Host } from '@stencil/core';

@Component({
  tag: 'dda-dropdown',
  styleUrls: ['../../global/input.css', '../../global/global.css'],
  shadow: false,
})
export class DdaDropdown {
  @Prop() label: string;
  @Prop() options: string; // Receive options as a string
  @Prop() selected: string;
  @Prop() disabled: boolean = false;
  @Prop() error: string;
  @Prop() helper_text: string;
  @Prop() type: 'bg-transparent' | 'bg-white' = 'bg-white';
  @Prop() size: 'small' | 'medium' = 'medium';
  @Prop() icon_mode: boolean = false; // New prop for icon mode
  @Prop() custom_class?: string = ''; 
  @Prop() component_mode?: string; 
  @Prop() button_id: string;
  @Prop() aria_label?: string;
  @Prop() arrow_button_name?: string;
  @Prop() dropdown_button_name?: string;

  @State() isopen: boolean = false;

  private get parsedOptions(): string[] {
    try {
      return JSON.parse(this.options);
    } catch {
      return [];
    }
  }

  toggleDropdown() {
    if (!this.disabled) {
      this.isopen = !this.isopen;
    }
  }

  selectOption(option: string) {
    if (!this.disabled) {
      this.selected = option;
      this.isopen = false;
    }
  }

  render() {  
    const containerClass = [
      'dda-input-container dda-inline-flex',
      this.disabled ? 'dda-input-disabled' : '',
      this.size ? `dda-input-size-${this.size}` : '',
      this.custom_class ? `${this.custom_class}` : '',
      this.component_mode,
    ].filter(Boolean).join(' ');

    return (
      <Host>
        <div class={containerClass}>
          {this.label && <label htmlFor={this.button_id} class="dda-input-label">{this.label}</label>}
          <div class={`dda-dropdown-container ${this.type}`}>
            <button id={this.button_id} name={this.arrow_button_name} aria-label={this.aria_label} type="button" class="dda-input-field dda-dropdown-header" onClick={() => this.toggleDropdown()}>
              <i class={`three-dots material-icons`}>{this.isopen ? 'more_vert' : 'more_vert'}</i>
              {!this.icon_mode && <span class="dda-dropdown-text"><span>{this.selected || 'Select an option'}</span> <i class={`material-icons`}>{this.isopen ? 'keyboard_arrow_up' : 'keyboard_arrow_down'}</i></span>
              }
            </button>
            {this.isopen && (
              <div class="dda-input-dropdown-list">
                {this.parsedOptions.length > 0 ? (
                  this.parsedOptions.map(option => (
                    <button type="button" name={this.dropdown_button_name}
                      class={`dda-input-dropdown-item ${this.selected === option ? 'selected' : ''}`}
                      onClick={() => {this.selectOption(option)}}
                    >
                      {option}
                    </button>
                  ))
                ) : (
                  <div class="dda-input-dropdown-item">No options available</div>
                )}
              </div>
            )}
          </div>
          {this.helper_text && <span class="dda-helper-text">{this.helper_text}</span>}
          {this.error && <span class="dda-error-message">{this.error}</span>}
        </div>
      </Host>
    );
  }
}

