import { Component, Prop, State, h, Host } from '@stencil/core';

@Component({
  tag: 'dda-number-field',
  styleUrls: ['../../global/input.css', '../../global/global.css'],
  shadow: false,
})
export class DdaNumberField {
  @Prop() placeholder: string;
  @Prop() label: string;
  @Prop() value: string;
  @Prop() helper_text: string;
  @Prop() error_message: string;
  @Prop() validation_type?: string;
  @Prop() size?: string;
  @Prop() input_status?: string; // JSON string of currency options
  @Prop() currencies: string;
  @Prop() selected_currency: string = 'USD';
  @State() is_focused: boolean = false;
  @Prop() custom_class?: string = '';
  @Prop() component_mode?: string; 
  @Prop() input_id: string;
  @Prop() aria_label?: string;
  @Prop() input_name?: string;
  @Prop() toggle_button_name?: string;
  @Prop() currency_button_name?: string;

  @State() isCurrencyDropdownOpen: boolean = false;

  handleInput(event) {
    const inputElement = event.target as HTMLInputElement
    const inputValue = inputElement.value.replace(/[^0-9.]/g, '');
    inputElement.value = inputValue;
  }
  handleFocus() {
    this.is_focused = true;
  }

  handleBlur() {
    this.is_focused = false;
  }
  toggleCurrencyDropdown() {
    this.isCurrencyDropdownOpen = !this.isCurrencyDropdownOpen;
    this.handleFocus();
    this.handleBlur();
  }

  selectCurrency(currency: string) {
    this.selected_currency = currency;
    this.isCurrencyDropdownOpen = false;
  }

  private get parsedCurrencies(): string[] {
    try {
      return JSON.parse(this.currencies);
    } catch {
      return [];
    }
  }

  render() {
    const containerClass = [
      'dda-input-container',
      this.validation_type ? `dda-validation-${this.validation_type}` : '',
      this.size ? `dda-input-size-${this.size}` : '',
      this.input_status ? `dda-input-${this.input_status}` : '',
      this.is_focused ? 'dda-input-focus' : '',
      this.error_message ? 'dda-error-message' : '',
      this.custom_class ? `${this.custom_class}` : '',
      this.component_mode,
    ].filter(Boolean).join(' ');

    return (
      <Host>
        <div class={containerClass}>
          {this.label && <label htmlFor={this.input_id} class="dda-input-label">{this.label}</label>}
          <div class="dda-input-field-group dda-number-field">
            <input
              id={this.input_id}
              name={this.input_name}
              aria-label={this.aria_label}
              type="text"
              placeholder={this.placeholder}
              value={this.value}
              pattern={"[0-9]*"}
              onInput={event => this.handleInput(event)}
              onFocus={this.handleFocus.bind(this)}
              onBlur={this.handleBlur.bind(this)}
              class="dda-field-group-input"
            />
            <div class="dda-input-dropdown-btn">
              <button name={this.toggle_button_name} type="button" class="dda-dropdown-select" onClick={() => this.toggleCurrencyDropdown()}>
                {this.selected_currency} <i class={`material-icons`}>{this.isCurrencyDropdownOpen ? 'keyboard_arrow_up' : 'keyboard_arrow_down'}</i>
              </button>
              {this.isCurrencyDropdownOpen && (
                <div class="dda-input-dropdown-list">
                  {this.parsedCurrencies.length > 0 ? (
                    this.parsedCurrencies.map(option => (
                      <button name={this.currency_button_name} type="button" class={`dda-input-dropdown-item ${this.selected_currency === option ? 'selected' : ''}`} onClick={() => this.selectCurrency(option)}>
                        {option}
                      </button>
                    ))
                  ) : (
                    <div class="dda-input-dropdown-item">No options available</div>
                  )}
                </div>
              )}
            </div>
          </div>
          {this.helper_text && <span class="dda-helper-text">{this.helper_text}</span>}
          {this.error_message && <span class="dda-error-message">{this.error_message}</span>}
        </div>
      </Host>
    );
  }
}

import { Component, Prop, h, Host, Watch } from '@stencil/core';

@Component({
  tag: 'dda-pagination',
  styleUrls: ['dda-pagination.css', '../../global/global.css'],
  shadow: false,
})
export class DdaPagination {
  @Prop() total_pages: number = 8;
  @Prop() current_page: number = 1;
  @Prop() type: 'simple-slider' | 'buttons' | 'text' | 'text-pages' | 'button-text' | 'buttons-pages' | 'full' = 'simple-slider';
  @Prop() custom_class: string = '';
  @Prop() component_mode?: string; 
  @Prop() simple_slider_prev_button: string;
  @Prop() simple_slider_next_button: string;
  @Prop() buttons_prev_button: string;
  @Prop() buttons_next_button: string;
  @Prop() text_prev_button: string;
  @Prop() text_next_button: string;
  @Prop() text_pages_prev_button: string;
  @Prop() text_pages_next_button: string;
  @Prop() button_text_prev_button: string;
  @Prop() button_text_next_button: string;
  @Prop() buttons_pages_prev_button: string;
  @Prop() buttons_pages_next_button: string;

  @Watch('total_pages')
  validateTotalPages(newValue: number) {
    if (newValue < 1) {
      this.total_pages = 1;
    }
  }

  @Watch('current_page')
  validateCurrentPage(newValue: number) {
    if (newValue < 1) {
      this.current_page = 1;
    } else if (newValue > this.total_pages) {
      this.current_page = this.total_pages;
    }
  }

  componentWillLoad() {
    this.validateTotalPages(this.total_pages);
    this.validateCurrentPage(this.current_page);
  }

  private renderPagination() {
    switch (this.type) {
      case 'simple-slider':
        return (
          <div class={`dda-pagination dda-pagination-simple-slider ${this.custom_class} ${this.component_mode}`}>
            <button name={this.simple_slider_prev_button} class="prev" disabled={this.current_page === 1} onClick={() => this.setcurrentpage(this.current_page - 1)}><i class="material-icons  material-symbols-outlined">arrow_back</i> Prev</button>
            <span>Page {this.current_page} of {this.total_pages}</span>
            <button name={this.simple_slider_next_button} class="next" disabled={this.current_page === this.total_pages} onClick={() => this.setcurrentpage(this.current_page + 1)}>Next <i class="material-icons  material-symbols-outlined">arrow_forward</i></button>
          </div>
        );
      case 'buttons':
        return (
          <div class={`dda-pagination dda-pagination-buttons ${this.custom_class} ${this.component_mode}`}>
            <button name={this.buttons_prev_button} class="prev" disabled={this.current_page === 1} onClick={() => this.setcurrentpage(this.current_page - 1)}><i class="material-icons  material-symbols-outlined">arrow_back</i> Prev</button>
            {this.renderPageButtons()}
            <button name={this.buttons_next_button} class="next" disabled={this.current_page === this.total_pages} onClick={() => this.setcurrentpage(this.current_page + 1)}>Next <i class="material-icons  material-symbols-outlined">arrow_forward</i></button>
          </div>
        );
      case 'text':
        return (
          <div class={`dda-pagination dda-pagination-text ${this.custom_class} ${this.component_mode}`}>
            <button name={this.text_prev_button} class="prev" disabled={this.current_page === 1} onClick={() => this.setcurrentpage(this.current_page - 1)}><i class="material-icons  material-symbols-outlined">arrow_back</i></button>
            <span>Page {this.current_page} of {this.total_pages}</span>
            <button name={this.text_next_button} class="next" disabled={this.current_page === this.total_pages} onClick={() => this.setcurrentpage(this.current_page + 1)}><i class="material-icons  material-symbols-outlined">arrow_forward</i></button>
          </div>
        );
      case 'text-pages':
        return (
          <div class={`dda-pagination dda-pagination-text-pages ${this.custom_class} ${this.component_mode}`}>
            <button name={this.text_pages_prev_button} class="prev" disabled={this.current_page === 1} onClick={() => this.setcurrentpage(this.current_page - 1)}><i class="material-icons  material-symbols-outlined">arrow_back</i></button>
            {this.renderPageButtons()}
            <button name={this.text_pages_next_button} class="next" disabled={this.current_page === this.total_pages} onClick={() => this.setcurrentpage(this.current_page + 1)}><i class="material-icons  material-symbols-outlined">arrow_forward</i></button>
          </div>
        );
      case 'button-text':
        return (
          <div class={`dda-pagination dda-pagination-button-text ${this.custom_class} ${this.component_mode}`}>
            <button name={this.button_text_prev_button} class="prev" disabled={this.current_page === 1} onClick={() => this.setcurrentpage(this.current_page - 1)}><i class="material-icons  material-symbols-outlined">arrow_back</i></button>
            {this.renderPageButtons()}
            <button name={this.button_text_next_button} class="next" disabled={this.current_page === this.total_pages} onClick={() => this.setcurrentpage(this.current_page + 1)}><i class="material-icons  material-symbols-outlined">arrow_forward</i></button>
          </div>
        );
      case 'buttons-pages':
        return (
          <div class={`dda-pagination dda-pagination-buttons-pages ${this.custom_class} ${this.component_mode}`}>
            <button name={this.buttons_pages_prev_button} class="prev" disabled={this.current_page === 1} onClick={() => this.setcurrentpage(this.current_page - 1)}><i class="material-icons  material-symbols-outlined">arrow_back</i></button>
            <button name={this.buttons_pages_next_button} class="next" disabled={this.current_page === this.total_pages} onClick={() => this.setcurrentpage(this.current_page + 1)}><i class="material-icons  material-symbols-outlined">arrow_forward</i></button>
          </div>
        );
      case 'full':
        return (
          <div class={`dda-pagination dda-pagination-full ${this.custom_class} ${this.component_mode}`}>
            {this.renderPageButtons()}
          </div>
        );
    }
  }


  private renderPageButtons() {
    const buttons = [];
    for (let i = 1; i <= this.total_pages; i++) {
      buttons.push(
        <button class={i === this.current_page ? 'active' : ''} onClick={() => this.setcurrentpage(i)}>
          {i}
        </button>
      );
    }
    return buttons;
  }

  private setcurrentpage(page: number) {
    if (page >= 1 && page <= this.total_pages) {
      this.current_page = page;
    }
  }

  render() {
    return (
      <Host>
        <div class={`dda-pagination-container`}>
          {this.renderPagination()}
        </div>
      </Host>
    );
  }
}

import { Component, Prop, State, h, Host } from '@stencil/core';
import { CountriesList } from '../../assets/countries';

@Component({
  tag: 'dda-phonefield',
  styleUrls: ['../../global/input.css', '../../global/global.css'],
  shadow: false,
})
export class DdaPhoneField {
  @Prop() label: string;
  @Prop() placeholder: string = 'Enter phone number';
  @Prop() helper_text: string;
  @Prop() validation_type?: string;
  @Prop() error_message: string;
  @Prop() disabled: boolean = false;
  @Prop() size?: string;
  @State() country_code: string = '+971';
  @State() country_flag: string = 'https://flagcdn.com/w320/ae.png'; // Default UAE flag
  @State() phone_number: string = '';
  @State() is_focused: boolean = false;
  @State() dropdown_open: boolean = false;
  @State() countries: { code: string; flag: string }[] = [];
  @Prop() custom_class: string;
  @Prop() component_mode?: string; 
  @Prop() input_id?: string;
  @Prop() aria_label: string;
  @Prop() button_id?: string;
  @Prop() button_aria_label: string;
  @Prop() toggle_button_name: string;
  @Prop() country_select_button_name: string;
  @Prop() phone_input_name: string;

  // componentWillLoad() {
  //   fetch('/path/to/countries.json')
  //     .then(response => response.json())
  //     .then(data => {
  //       this.countries = data;
  //     });
  // }

  componentWillLoad() {
    this.countries = CountriesList;
  }
  toggleDropdown() {
    this.dropdown_open = !this.dropdown_open;
  }

  selectCountry(country: { code: string; flag: string }) {
    this.country_code = country.code;
    this.country_flag = country.flag;
    this.dropdown_open = false;
  }

  handleFocus() {
    this.is_focused = true;
  }

  handleBlur() {
    this.is_focused = false;
  }

  handlephonenumberChange(event: Event) {
    const target = event.target as HTMLInputElement;
    const targetvalue = target.value.replace(/[^0-9.]/g, '');
    this.phone_number = targetvalue;
    }

  render() {
    const inputClass = `${this.component_mode} ${this.size ? `dda-input-size-${this.size}` : ''} ${this.error_message ? `dda-error-message` : ''}  ${this.validation_type ? `dda-validation-${this.validation_type}` : ''}  ${this.is_focused ? 'dda-input-focus' : ''} ${this.phone_number ? 'dda-input-focus-filled' : '' }`;
    return (
      <Host>
        <div class={`dda-input-container ${inputClass} ${this.custom_class} ${this.disabled ? 'dda-input-disabled' : ''}`}>
          {this.label && <label htmlFor={this.input_id} class="dda-input-label">{this.label}</label>}
          <div class={`dda-input-field-group dda-phone-field`}>
            <div class="dda-input-dropdown-btn">
              <button type="button" name={this.toggle_button_name}  class="dda-dropdown-select" onClick={() => this.toggleDropdown()}>
                <img src={this.country_flag} alt="" width="20" /> {this.country_code} <i class={`material-icons`}>{this.dropdown_open ? 'keyboard_arrow_down' : 'keyboard_arrow_down'}</i>
              </button>
              {this.dropdown_open && (
                <div class="dda-input-dropdown-list">
                  {this.countries.map(country => (
                    <button id={this.button_id} name={this.country_select_button_name} aria-label={this.button_aria_label} type="button" class="dda-input-dropdown-item" onClick={() => this.selectCountry(country)}>
                      <img src={country.flag} alt="" width="20" /> {country.code}
                    </button>
                  ))}
                </div>
              )}
            </div>
            <input
              id={this.input_id}
              name={this.phone_input_name}
              aria-label={this.aria_label}
              type="number"
              class={`dda-field-group-input`}
              placeholder={this.placeholder}
              inputmode='numeric'
              pattern={"[0-9]*"}
              value={this.phone_number}
              onInput={this.handlephonenumberChange.bind(this)}
              onFocus={this.handleFocus.bind(this)}
              onBlur={this.handleBlur.bind(this)}
              disabled={this.disabled}
            />
          </div>
          {this.helper_text && !this.validation_type && <span class="dda-helper-text">{this.helper_text}</span>}
          {this.error_message && <span class="dda-error-message">{this.error_message}</span>}
        </div>
      </Host>
    );
  }
}

